<?php
/**
 * IEMA CRMOps — AI Drafts Review Queue
 * -----------------------------------------------------------------------
 * Every draft here was generated by cron/generate-followup-drafts.php and
 * starts as 'pending_review'. Nothing leaves this queue without a human
 * clicking Approve — this page is the human-in-the-loop gate the AI spec
 * requires. "Approve & Send" attempts server-side mail() (unreliable on
 * many hosts) AND always shows a mailto: fallback so approval never
 * dead-ends.
 * -----------------------------------------------------------------------
 */
require_once __DIR__ . '/config.php';
require_login();

$role = current_role();
$uid = (int) ($_SESSION['user_id'] ?? 0);
$userName = $_SESSION['user_name'] ?? 'BD Team';
$error = '';
$success = '';

if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $draftId = (int) ($_POST['draft_id'] ?? 0);
    $action = $_POST['action'] ?? '';

    $draftStmt = $pdo->prepare('SELECT d.*, l.company_name, COALESCE(c.primary_contact_email, l.contact_email) AS contact_email, l.assigned_to FROM scheduled_email_drafts d JOIN leads l ON l.id = d.lead_id LEFT JOIN clients c ON c.id = l.client_id WHERE d.id = ?');
    $draftStmt->execute([$draftId]);
    $draft = $draftStmt->fetch();

    $canManage = $draft && ($role !== 'bd_officer' || (int) $draft['assigned_to'] === $uid);

    if (!$draft || !$canManage) {
        $error = 'Draft not found or you do not have permission to manage it.';
    } elseif ($action === 'dismiss') {
        $pdo->prepare("UPDATE scheduled_email_drafts SET status = 'dismissed', reviewed_by = ?, reviewed_at = NOW() WHERE id = ?")->execute([$uid, $draftId]);
        $success = 'Draft dismissed.';
    } elseif ($action === 'approve_send') {
        $editedSubject = trim($_POST['subject'] ?? $draft['subject']);
        $editedBody = trim($_POST['body'] ?? $draft['body']);

        $pdo->prepare("UPDATE scheduled_email_drafts SET subject = ?, body = ?, status = 'approved', reviewed_by = ?, reviewed_at = NOW() WHERE id = ?")
            ->execute([$editedSubject, $editedBody, $uid, $draftId]);

        if (!empty($draft['contact_email'])) {
            $sent = attempt_send_email($draft['contact_email'], $editedSubject, $editedBody, $userName, $_SESSION['user_email'] ?? 'noreply@iema-standards.com');
            if ($sent) {
                $pdo->prepare("UPDATE scheduled_email_drafts SET status = 'sent', sent_at = NOW() WHERE id = ?")->execute([$draftId]);
                $success = 'Approved and sent to ' . e($draft['contact_email']) . '.';
            } else {
                $success = 'Approved. Automatic sending isn\'t working on this server — use the "Open in Email App" link below to send it yourself.';
            }
        } else {
            $success = 'Approved. This lead has no contact email on file — add one on the lead record, or use the copy button to send manually.';
        }

        $audit = $pdo->prepare('INSERT INTO audit_log (user_id, action, entity_type, entity_id, details) VALUES (?,?,?,?,?)');
        $audit->execute([$uid, 'update', 'scheduled_email_draft', $draftId, 'Approved follow-up draft']);
    }
}

$scopeSql = $role === 'bd_officer' ? 'AND l.assigned_to = ?' : '';
$scopeParams = $role === 'bd_officer' ? [$uid] : [];

$stmt = $pdo->prepare("
    SELECT d.*, l.company_name, COALESCE(c.primary_contact_email, l.contact_email) AS contact_email, l.stage, u.name AS officer_name
    FROM scheduled_email_drafts d
    JOIN leads l ON l.id = d.lead_id
    LEFT JOIN clients c ON c.id = l.client_id
    LEFT JOIN users u ON u.id = l.assigned_to
    WHERE d.status = 'pending_review' $scopeSql
    ORDER BY d.created_at ASC
");
$stmt->execute($scopeParams);
$pendingDrafts = $stmt->fetchAll();

$historyStmt = $pdo->prepare("
    SELECT d.*, l.company_name
    FROM scheduled_email_drafts d
    JOIN leads l ON l.id = d.lead_id
    WHERE d.status IN ('sent','dismissed') $scopeSql
    ORDER BY d.reviewed_at DESC LIMIT 10
");
$historyStmt->execute($scopeParams);
$history = $historyStmt->fetchAll();

require_once __DIR__ . '/includes/header.php';
?>

<?php
// Summary numbers — from the pending queue and recent history already loaded.
$adSent      = count(array_filter($history, fn($h) => $h['status'] === 'sent'));
$adDismissed = count($history) - $adSent;
$adNoEmail   = count(array_filter($pendingDrafts, fn($d) => empty($d['contact_email'])));
$adOldest    = $pendingDrafts[0]['created_at'] ?? null;
$adOldestDays = $adOldest ? (int) floor((time() - strtotime($adOldest)) / 86400) : null;
?>
