    <p>Follow-up emails the AI drafted on schedule for stale leads. Nothing sends until you approve it.</p>
  </div>
</div>

<?php if ($error): ?><div class="alert error"><?php echo icon('alert'); ?><span><?php echo e($error); ?></span></div><?php endif; ?>
