      <div class="tile-label">Awaiting review</div>
      <div class="tile-icon"><?php echo icon('mail'); ?></div>
    </div>
    <div class="tile-value"><?php echo count($pendingDrafts); ?></div>
    <div class="tile-sub">
      <?php if ($adOldestDays !== null): ?>Oldest queued <?php echo $adOldestDays === 0 ? 'today' : $adOldestDays . ' day' . ($adOldestDays === 1 ? '' : 's') . ' ago'; ?><?php echo $adNoEmail ? ' · ' . $adNoEmail . ' missing an email' : ''; ?><?php else: ?>Queue is clear<?php endif; ?>
    </div>
