      <div class="tile-label">Sent</div>
      <div class="tile-icon green"><?php echo icon('send'); ?></div>
    </div>
    <div class="tile-value"><?php echo $adSent; ?></div>
    <div class="tile-sub">Of the last <?php echo count($history); ?> reviewed</div>
  </section>
  <section class="tile span-4 ad-half">
    <div class="ad-kpi">
      <div class="tile-label">Dismissed</div>
      <div class="tile-icon navy"><?php echo icon('x'); ?></div>
    </div>
    <div class="tile-value"><?php echo $adDismissed; ?></div>
    <div class="tile-sub">Of the last <?php echo count($history); ?> reviewed</div>
  </section>

  <div class="span-8 ad-stack">
  <?php if (empty($pendingDrafts)): ?>
    <section class="tile">
      <div class="empty-state">
        <div class="icon-button"><?php echo icon('mail'); ?></div>
        <p>No drafts waiting for review. The scheduled generator queues these automatically for leads that have gone quiet 14+ days — check back after it next runs, or trigger it manually if you're testing.</p>
      </div>
    </section>
  <?php else: foreach ($pendingDrafts as $d): ?>
    <section class="tile ad-draft">
      <div class="tile-head">
        <div>
          <div class="ad-company"><?php echo e($d['company_name']); ?></div>
