            <?php if (!empty($d['officer_name'])): ?><span>· <?php echo e($d['officer_name']); ?></span><?php endif; ?>
            <?php if (!empty($d['contact_email'])): ?><span>· <?php echo e($d['contact_email']); ?></span><?php endif; ?>
          </div>
