               href="mailto:<?php echo e($d['contact_email'] ?? ''); ?>?subject=<?php echo rawurlencode($d['subject']); ?>&body=<?php echo rawurlencode($d['body']); ?>">
              <?php echo icon('mail'); ?> Open in Email App
            </a>
